{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "C22 reports fexofenadine absolute oral bioavailability of 33% in healthy subjects, directly above the 20% threshold and supporting high."
    },
    {
      "card_ids": ["C61"],
      "claim": "C61 reports rosuvastatin absolute oral bioavailability of 20.1% in healthy volunteers, at/above the 20% threshold and supporting high."
    },
    {
      "card_ids": ["C73"],
      "claim": "C73 reports propranolol absolute oral bioavailability as low as 16% for an 80-mg oral dose, a contradictory value; however, the strongest ordinary absolute record for propranolol is 37% (C05), and most evidence molecules support high."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C73"],
  "decision_summary": "Across the high-transfer evidence molecules, the strongest ordinary absolute/systemic oral bioavailability values are predominantly above 20%, including 33%, 37%, 38%, 45.2%, 50%, 52%, 20.1%, 34.3%, and ~100%. Isolated low values and one qualitative record do not outweigh this pattern, so high is predicted.",
  "evidence_gaps": [
    "Ilomastat record C26 is qualitative ('not good') and lacks a numeric threshold-relevant value, so it is uninformative for the F>=20% decision.",
    "A few low absolute values for propranolol (C73) and labetalol (C39) introduce minor uncertainty, but they are outweighed by stronger ordinary absolute measurements.",
    "Altered-condition records such as apple juice (C48), microdose (C51), and cirrhotic patients (C07) were discounted from the decision."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C22", "C61"],
  "revision_action": "initial",
  "supportive_card_ids": ["C22", "C61"]
}

